<script setup lang="ts">
import {statusLabels,type CustomerRequestSummary} from '@ellas/shared';
definePageMeta({middleware:'customer'});useHead({title:'Mis pedidos'});
const account=useAccount();const page=ref(1);const error=ref('');const request=useRequestFetch();
const {data,status,refresh}=await useAsyncData('customer-requests',()=>request<{requests:CustomerRequestSummary[];total:number;pages:number}>('/api/customer/requests',{query:{page:page.value}}),{watch:[page]});
async function logout(){try{await account.logout();await navigateTo('/mi-cuenta/entrar');}catch(e){error.value=errorMessage(e);}}
const date=(value:string)=>new Intl.DateTimeFormat('es-ES',{dateStyle:'medium'}).format(new Date(value));
</script>
<template><div class="container customer-page"><header class="customer-heading"><div><span class="eyebrow">HOLA, {{account.user.value?.name}}</span><h1>Mis <span class="serif-word">pedidos.</span></h1><p>Consulta cómo va tu equipo y revisa las prendas que has elegido.</p></div><button class="text-link" @click="logout">Cerrar sesión <AppIcon name="LogOut" :size="17"/></button></header><p v-if="account.user.value?.demo" class="alert" role="status">Cuenta de demostración. Sus solicitudes son ficticias y no generan avisos por email.</p><p v-if="error" class="alert error" role="alert">{{error}}</p><div v-if="status==='error'" class="alert error" role="alert">No se han podido cargar tus pedidos. <button class="text-link" @click="refresh()">Reintentar</button></div><p v-else-if="status==='pending'" role="status">Cargando tus pedidos…</p><div v-else-if="!data?.requests.length" class="customer-empty"><AppIcon name="ShoppingBag" :size="36"/><h2>Tu próximo equipo empieza aquí.</h2><p>Los pedidos que envíes con tu sesión iniciada aparecerán en este espacio.</p><NuxtLink to="/hacer-pedido" class="button dark">Hacer un pedido <AppIcon name="ArrowRight"/></NuxtLink></div><div v-else class="customer-orders"><NuxtLink v-for="order in data.requests" :key="order._id" :to="`/mi-cuenta/pedidos/${order._id}`" class="customer-order"><div><small>{{order.type==='pedido'?'PEDIDO':'PRESUPUESTO'}} · {{date(order.createdAt)}}</small><h2>{{order.number}}</h2><span>{{order.quantity}} prendas <b v-if="order.demo" class="demo-data">Ejemplo ficticio</b></span></div><div><span class="status-badge">{{statusLabels[order.status]}}</span><AppIcon name="ArrowUpRight"/></div></NuxtLink></div><nav v-if="(data?.pages||0)>1" class="customer-pagination" aria-label="Páginas de mis pedidos"><button class="button outline" :disabled="page===1" @click="page--">Anterior</button><span>{{page}} / {{data?.pages}}</span><button class="button outline" :disabled="page>=(data?.pages||0)" @click="page++">Siguiente</button></nav><NuxtLink to="/hacer-pedido" class="text-link customer-new">Preparar otro pedido <AppIcon name="ArrowRight" :size="17"/></NuxtLink></div></template>
